import { existsSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { SignDatabase } from "@jsesh/glyphs";
import { LAST_USED_KEY, PaletteController, PseudoFamily, USER_PALETTE_KEY } from "../src/controller.js";
import { memoryPaletteStorage } from "../src/storage.js";

const file = join(import.meta.dirname, "../../glyphs/data/sign-info.json");

// The data is generated by `./gradlew :jseshJsExport:exportSignInfo`.
describe.skipIf(!existsSync(file))("PaletteController", () => {
  const db = new SignDatabase(JSON.parse(readFileSync(file, "utf-8")));
  const palette = (initial = {}) => new PaletteController(db, { storage: memoryPaletteStorage(initial) });

  it("starts with the first family, its tags, and its first sign selected", () => {
    const s = palette().state;
    expect(s.family).toBe("A");
    expect(s.displayed).toContain("A1");
    expect(s.tags[0]).toBe("All");
    expect(s.tag).toBe("All");
    expect(s.selected).toBe(s.displayed[0]);
    expect(s.info?.code).toBe(s.selected);
  });

  it("offers the families and the pseudo-families", () => {
    const values = palette().familyOptions.map((o) => o.value);
    expect(values[0]).toBe(PseudoFamily.LAST_USED);
    expect(values).toContain("A");
    expect(values).toContain(PseudoFamily.ALL);
  });

  it("shows variants only on demand", () => {
    const p = palette();
    const basic = p.state.displayed.length;
    p.setShowAllVariants(true);
    expect(p.state.displayed.length).toBeGreaterThan(basic);
    expect(p.state.displayed).toContain("A1A");
  });

  it("narrows by tag, then by secondary tag", () => {
    const p = palette();
    p.setTag("seated");
    const seated = p.state.displayed;
    expect(seated).toContain("A1");
    expect(seated.every((c) => db.getTagsForSign(c).includes("seated"))).toBe(true);
    expect(p.state.secondaryTags[0]).toBe("");
    const secondary = p.state.secondaryTags[1];
    p.setSecondaryTag(secondary);
    expect(p.state.displayed.length).toBeLessThanOrEqual(seated.length);
    expect(p.state.displayed.every((c) => db.getTagsForSign(c).includes(secondary))).toBe(true);
  });

  it("searches by value and by code, and leaves the family", () => {
    const p = palette();
    p.search("nfr");
    expect(p.state.family).toBe("");
    expect(p.state.tags).toEqual([]);
    expect(p.state.displayed[0]).toBe("F35");
    expect(p.state.selected).toBe("F35");
    p.search("A1");
    expect(p.state.displayed[0]).toBe("A1");
    expect(p.state.displayed).toContain("A10");
  });

  it("goes from variants to variants of variants, and from parts to containers", () => {
    const p = palette();
    p.select("A1");
    p.showVariants();
    const level1 = p.state.displayed;
    expect(level1).toContain("A1");
    expect(level1).toContain("A1B");
    p.showVariants();
    expect(p.state.displayed.length).toBeGreaterThanOrEqual(level1.length);
    const container = db.getCodesSet().find((c) => db.getSignsIn(c).length > 0)!;
    const part = db.getSignsIn(container)[0];
    p.select(part);
    p.showContaining();
    expect(p.state.displayed).toContain(container);
  });

  it("remembers the previous signs for back()", () => {
    const p = palette();
    p.select("A1");
    p.select("A2");
    expect(p.state.canGoBack).toBe(true);
    p.back();
    expect(p.state.selected).toBe("A1");
  });

  it("reveals a sign which is not displayed", () => {
    const p = palette();
    p.reveal("F35");
    expect(p.state.selected).toBe("F35");
    expect(p.state.displayed[0]).toBe("F35");
    expect(p.state.family).toBe("");
  });

  it("moves the selection in the displayed list, within bounds", () => {
    const p = palette();
    const [first, second] = p.state.displayed;
    p.move(-1);
    expect(p.state.selected).toBe(first);
    p.move(1);
    expect(p.state.selected).toBe(second);
  });

  it("filters the displayed signs by part", () => {
    const p = palette();
    p.setFamily(PseudoFamily.ALL);
    const container = db.getCodesSet().find((c) => db.getSignsIn(c).length > 0)!;
    const part = db.getSignsIn(container)[0];
    p.filterContaining(part);
    expect(p.state.displayed).toContain(container);
    expect(p.state.displayed.length).toBeLessThan(db.getCodesSet().length);
  });

  it("keeps the user palette and the latest signs in the storage", () => {
    const storage = memoryPaletteStorage();
    const p = new PaletteController(db, { storage });
    const chosen: string[] = [];
    p.onSignChosen((c) => chosen.push(c));
    p.select("A1");
    p.setInUserPalette(true);
    p.choose();
    p.choose("A2");
    expect(chosen).toEqual(["A1", "A2"]);
    expect(storage.load(USER_PALETTE_KEY)).toEqual(["A1"]);
    expect(storage.load(LAST_USED_KEY)).toEqual(["A1", "A2"]);
    expect(p.state.info?.inUserPalette).toBe(true);

    const again = new PaletteController(db, { storage, initialFamily: PseudoFamily.LAST_USED });
    expect(again.state.displayed).toEqual(["A1", "A2"]);
  });

  it("notifies subscribers, and caches the state between changes", () => {
    const p = palette();
    let calls = 0;
    const stop = p.subscribe(() => calls++);
    const state = p.state;
    expect(p.state).toBe(state);
    p.select("A2");
    expect(calls).toBe(1);
    expect(p.state).not.toBe(state);
    stop();
    p.select("A3");
    expect(calls).toBe(1);
  });

  it("describes the selected sign", () => {
    const p = palette();
    p.select("A1");
    const info = p.state.info!;
    expect(info.values).toContain("i");
    expect(info.tags).toContain("seated");
    expect(info.variants.find((v) => v.code === "A1B")?.typeLabel).toBeTruthy();
  });
});
